(()=>{"use strict";const SCENE_IONO_RADIUS=5.274682153508083;function latLonAltToVector3(latDeg,lonDeg,altKm=0){const phi=(latDeg||0)*(Math.PI/180),lambda=(lonDeg||0)*(Math.PI/180),r=5*(1+Math.max(0,altKm)/6371);return new window.THREE.Vector3(r*Math.cos(phi)*Math.cos(lambda),r*Math.sin(phi),-r*Math.cos(phi)*Math.sin(lambda))}function calculateIpp3D(stationPos3D,satellitePos3D){if(!stationPos3D||!satellitePos3D)return null;const dir=satellitePos3D.clone().sub(stationPos3D).normalize(),b=2*stationPos3D.dot(dir),c=stationPos3D.lengthSq()-SCENE_IONO_RADIUS*SCENE_IONO_RADIUS,discr=b*b-4*c;if(discr<=0)return null;const t=(-b+Math.sqrt(discr))/2;return stationPos3D.clone().add(dir.multiplyScalar(t))}window.Globe3DMath={RE_EARTH_KM:6371,SCENE_EARTH_RADIUS:5,H_IONO_KM:350,SCENE_IONO_RADIUS,latLonAltToVector3,calculateIpp3D}})();
